// Android-only native configuration that app.json can't express
// (docs/android-port-plan.md §3.6). android/ is generated by prebuild and
// gitignored, so everything Android needs beyond app.json lives here. iOS is
// untouched: every mod below is an Android mod.
//
//  1. AsyncStorage database size. On Android AsyncStorage is SQLite capped at
//     6 MB by default; document records (with their recognised text) live in
//     it (lib/storage.ts), so a heavy user would hit the cap and saves would
//     fail. AsyncStorage reads the cap from the Gradle property
//     AsyncStorage_db_size_in_MB (its android/config.gradle).
//  2. Home-screen shortcuts mirroring the iOS quick actions
//     (UIApplicationShortcutItems in app.json): res/xml/scankit_shortcuts.xml,
//     their labels and icons, and the meta-data on MainActivity. Each starts
//     modules/vision-ocr's QuickActionTrampolineActivity with the iOS item
//     type as extra "type", so lib/quick-actions.ts handles both platforms
//     with one map.
const {
  AndroidConfig,
  withAndroidManifest,
  withDangerousMod,
  withGradleProperties,
} = require('expo/config-plugins');
const fs = require('fs');
const path = require('path');

const SHORTCUTS = [
  { id: 'scan', type: 'com.6yato9.scan-kit.scan', short: 'Scan', long: 'Scan document', icon: 'camera' },
  { id: 'import_photos', type: 'com.6yato9.scan-kit.import-photos', short: 'Import photos', long: 'Import photos', icon: 'photos' },
  { id: 'import_file', type: 'com.6yato9.scan-kit.import-file', short: 'Import file', long: 'Import file', icon: 'folder' },
  { id: 'search', type: 'com.6yato9.scan-kit.search', short: 'Search', long: 'Search documents', icon: 'search' },
];

// Material Symbols glyphs (Apache-2.0), 24-unit viewport.
const GLYPHS = {
  camera:
    'M12,15.2a3.2,3.2 0,1 0,0 -6.4a3.2,3.2 0,0 0,0 6.4z M9,2L7.17,4H4c-1.1,0 -2,0.9 -2,2v12c0,1.1 0.9,2 2,2h16c1.1,0 2,-0.9 2,-2V6c0,-1.1 -0.9,-2 -2,-2h-3.17L15,2H9zM12,17c-2.76,0 -5,-2.24 -5,-5s2.24,-5 5,-5 5,2.24 5,5 -2.24,5 -5,5z',
  photos:
    'M22,16V4c0,-1.1 -0.9,-2 -2,-2H8c-1.1,0 -2,0.9 -2,2v12c0,1.1 0.9,2 2,2h12c1.1,0 2,-0.9 2,-2zM11,12l2.03,2.71L16,11l4,5H8l3,-4zM2,6v14c0,1.1 0.9,2 2,2h14v-2H4V6H2z',
  folder:
    'M10,4H4c-1.1,0 -1.99,0.9 -1.99,2L2,18c0,1.1 0.9,2 2,2h16c1.1,0 2,-0.9 2,-2V8c0,-1.1 -0.9,-2 -2,-2h-8l-2,-2z',
  search:
    'M15.5,14h-0.79l-0.28,-0.27C15.41,12.59 16,11.11 16,9.5 16,5.91 13.09,3 9.5,3S3,5.91 3,9.5 5.91,16 9.5,16c1.61,0 3.09,-0.59 4.23,-1.57l0.27,0.28v0.79l5,4.99L20.49,19l-4.99,-5zM9.5,14C7.01,14 5,11.99 5,9.5S7.01,5 9.5,5 14,7.01 14,9.5 11.99,14 9.5,14z',
};

// lib/theme.ts light accent and accentLight.
const ICON_BACKGROUND = '#E8F5FA';
const ICON_GLYPH = '#0A7EA4';

const DB_SIZE_MB = 512;

function withAsyncStorageSize(config) {
  return withGradleProperties(config, cfg => {
    const key = 'AsyncStorage_db_size_in_MB';
    cfg.modResults = cfg.modResults.filter(p => !(p.type === 'property' && p.key === key));
    cfg.modResults.push({ type: 'property', key, value: String(DB_SIZE_MB) });
    return cfg;
  });
}

function shortcutsXml(pkg) {
  const items = SHORTCUTS.map(
    s => `  <shortcut
    android:shortcutId="${s.id}"
    android:enabled="true"
    android:icon="@drawable/scankit_shortcut_${s.icon}"
    android:shortcutShortLabel="@string/scankit_shortcut_${s.id}_short"
    android:shortcutLongLabel="@string/scankit_shortcut_${s.id}_long">
    <intent
      android:action="expo.modules.visionocr.QUICK_ACTION"
      android:targetPackage="${pkg}"
      android:targetClass="expo.modules.visionocr.QuickActionTrampolineActivity">
      <extra android:name="type" android:value="${s.type}" />
    </intent>
  </shortcut>`,
  );
  return `<?xml version="1.0" encoding="utf-8"?>
<!-- Generated by plugins/with-android-platform.js: the iOS quick actions as Android app shortcuts. -->
<shortcuts xmlns:android="http://schemas.android.com/apk/res/android">
${items.join('\n')}
</shortcuts>
`;
}

function iconXml(glyph) {
  // Adaptive icon: a light accent disc with the glyph inside the 66 dp safe zone.
  return `<?xml version="1.0" encoding="utf-8"?>
<adaptive-icon xmlns:android="http://schemas.android.com/apk/res/android">
  <background android:drawable="@color/scankit_shortcut_background" />
  <foreground>
    <vector
      android:width="108dp"
      android:height="108dp"
      android:viewportWidth="108"
      android:viewportHeight="108">
      <group android:translateX="33" android:translateY="33" android:scaleX="1.75" android:scaleY="1.75">
        <path android:fillColor="${ICON_GLYPH}" android:pathData="${GLYPHS[glyph]}" />
      </group>
    </vector>
  </foreground>
</adaptive-icon>
`;
}

function stringsXml() {
  const esc = s => s.replace(/'/g, "\\'");
  const rows = SHORTCUTS.flatMap(s => [
    `  <string name="scankit_shortcut_${s.id}_short">${esc(s.short)}</string>`,
    `  <string name="scankit_shortcut_${s.id}_long">${esc(s.long)}</string>`,
  ]);
  return `<?xml version="1.0" encoding="utf-8"?>
<resources>
${rows.join('\n')}
  <color name="scankit_shortcut_background">${ICON_BACKGROUND}</color>
</resources>
`;
}

function withShortcutResources(config) {
  return withDangerousMod(config, [
    'android',
    cfg => {
      const pkg = cfg.android?.package;
      if (!pkg) throw new Error('with-android-platform: android.package is required');
      const res = path.join(cfg.modRequest.platformProjectRoot, 'app/src/main/res');
      const write = (rel, text) => {
        const file = path.join(res, rel);
        fs.mkdirSync(path.dirname(file), { recursive: true });
        fs.writeFileSync(file, text);
      };
      write('xml/scankit_shortcuts.xml', shortcutsXml(pkg));
      write('values/scankit_shortcuts.xml', stringsXml());
      for (const glyph of Object.keys(GLYPHS)) write(`drawable/scankit_shortcut_${glyph}.xml`, iconXml(glyph));
      return cfg;
    },
  ]);
}

function withShortcutsMetaData(config) {
  return withAndroidManifest(config, cfg => {
    const activity = AndroidConfig.Manifest.getMainActivityOrThrow(cfg.modResults);
    const meta = (activity['meta-data'] ??= []);
    const name = 'android.app.shortcuts';
    activity['meta-data'] = meta.filter(m => m.$['android:name'] !== name);
    activity['meta-data'].push({ $: { 'android:name': name, 'android:resource': '@xml/scankit_shortcuts' } });
    return cfg;
  });
}

module.exports = function withAndroidPlatform(config) {
  config = withAsyncStorageSize(config);
  config = withShortcutResources(config);
  config = withShortcutsMetaData(config);
  return config;
};

module.exports.SHORTCUTS = SHORTCUTS;
module.exports.shortcutsXml = shortcutsXml;
